function validate([n, delay, forget]) {
  if (![n, delay, forget].every(Number.isInteger)) return 'n, delay and forget are whole numbers.';
  if (n < 2 || n > 1000) return 'n is between 2 and 1000.';
  if (delay < 1 || delay >= forget || forget > n) return 'They must satisfy 1 <= delay < forget <= n.';
  return null;
}

