function peopleAwareOfSecret(n, delay, forget) {
  const MOD = 1000000007;
  const learned = new Array(n + 1).fill(0);
  learned[1] = 1;
  let sharing = 0;

  for (let day = 2; day <= n; day++) {
    if (day - delay >= 1) {
      sharing = (sharing + learned[day - delay]) % MOD;
    }
    if (day - forget >= 1) {
      sharing = (sharing - learned[day - forget] + MOD) % MOD;
    }
    learned[day] = sharing;
  }

  let aware = 0;
  for (let day = n - forget + 1; day <= n; day++) {
    aware = (aware + learned[day]) % MOD;
  }
  return aware;
}

