function peopleAwareOfSecret(n, delay, forget) {
  // Simulate day by day with groups of people who learned the secret on the same day.
  const MOD = 1000000007;
  let groups = [{ start: 1, count: 1 }];
  for (let day = 2; day <= n; day++) {
    groups = groups.filter(g => day - g.start < forget);
    let fresh = 0;
    for (const g of groups) {
      if (day - g.start >= delay) fresh = (fresh + g.count) % MOD;
    }
    groups.push({ start: day, count: fresh });
  }
  return groups.reduce((total, g) => (total + g.count) % MOD, 0);
}

