function generate(rand, size) {
  const n = size === 'large' ? 500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 14);
  const forget = 2 + Math.floor(rand() * (n - 1));
  const delay = 1 + Math.floor(rand() * (forget - 1));
  return [n, delay, forget];
}
